//! Proves the spewbox enums against the official ACE source extract.
//! `tests/fixtures/spewbox_enums.csv` is generated by `oracle/spewbox_enums_generate.py`
//! from ACE `Source/ACE.Entity/Enum` at the pinned commit (see the fixture header hashes).
//! Each CSV row must map name -> value -> enum and back. Undefined values must return `None`.
use bace_wire::{ChatMessageType, WeenieError, WeenieErrorWithString};
use std::collections::BTreeSet;
use std::fmt::Debug;

const FIXTURE: &str = include_str!("fixtures/spewbox_enums.csv");
const PIN: &str = "47edade3bd3f6044b676d4eb877c4965c7eda62b";
const WEENIE_ERROR_COUNT: usize = 369;
const WEENIE_ERROR_WITH_STRING_COUNT: usize = 113;
const CHAT_MESSAGE_TYPE_COUNT: usize = 31;

struct Row<'a> {
    enum_name: &'a str,
    name: &'a str,
    value: u32,
}

fn fixture_rows() -> Vec<Row<'static>> {
    FIXTURE
        .lines()
        .filter(|line| !line.is_empty() && !line.starts_with('#') && *line != "enum,name,value")
        .map(|line| {
            let mut fields = line.split(',');
            let (Some(enum_name), Some(name), Some(value), None) =
                (fields.next(), fields.next(), fields.next(), fields.next())
            else {
                panic!("malformed fixture row: {line}");
            };
            Row {
                enum_name,
                name,
                value: value.parse().expect("fixture value is u32"),
            }
        })
        .collect()
}

/// Mirrors the generator: the ACE name with underscores removed and the first letter uppercased.
fn rust_ident(ace_name: &str) -> String {
    let stripped: String = ace_name.chars().filter(|c| *c != '_').collect();
    let mut chars = stripped.chars();
    match chars.next() {
        Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
        None => String::new(),
    }
}

fn check<E: Copy + Debug + PartialEq>(
    enum_name: &str,
    expected: usize,
    all: &[E],
    from_u32: impl Fn(u32) -> Option<E>,
    value: impl Fn(E) -> u32,
) {
    let rows: Vec<Row<'_>> = fixture_rows()
        .into_iter()
        .filter(|row| row.enum_name == enum_name)
        .collect();
    assert_eq!(rows.len(), expected, "{enum_name}: fixture row count");
    assert_eq!(all.len(), expected, "{enum_name}: ALL member count");
    assert!(
        all.windows(2).all(|pair| value(pair[0]) < value(pair[1])),
        "{enum_name}: ALL must be strictly sorted by value"
    );

    for row in &rows {
        let member = from_u32(row.value)
            .unwrap_or_else(|| panic!("{enum_name}: {} = {} has no member", row.name, row.value));
        assert_eq!(value(member), row.value, "{enum_name}: {} value", row.name);
        assert_eq!(
            format!("{member:?}"),
            rust_ident(row.name),
            "{enum_name}: {} name",
            row.name
        );
        let by_name = all
            .iter()
            .copied()
            .find(|candidate| format!("{candidate:?}") == rust_ident(row.name))
            .unwrap_or_else(|| panic!("{enum_name}: {} not found by name", row.name));
        assert_eq!(
            value(by_name),
            row.value,
            "{enum_name}: {} name->value",
            row.name
        );
        assert_eq!(
            from_u32(value(by_name)),
            Some(by_name),
            "{enum_name}: {} round trip",
            row.name
        );
    }

    let mut csv_values: Vec<u32> = rows.iter().map(|row| row.value).collect();
    csv_values.sort_unstable();
    assert!(
        csv_values.windows(2).all(|pair| pair[0] < pair[1]),
        "{enum_name}: fixture values must be unique"
    );
    let mut member_values: Vec<u32> = all.iter().map(|member| value(*member)).collect();
    member_values.sort_unstable();
    assert_eq!(
        csv_values, member_values,
        "{enum_name}: members and fixture differ"
    );

    let known: BTreeSet<u32> = csv_values.iter().copied().collect();
    let max = csv_values.last().copied().unwrap_or(0);
    for candidate in 0..=max.saturating_add(2) {
        if !known.contains(&candidate) {
            assert!(
                from_u32(candidate).is_none(),
                "{enum_name}: undefined value {candidate:#x} must not map to a member"
            );
        }
    }
    for candidate in [u32::MAX, 0x8000_0000, 0x7FFF_FFFF] {
        assert!(
            from_u32(candidate).is_none(),
            "{enum_name}: {candidate:#x} must be rejected"
        );
    }
}

#[test]
fn fixture_is_pinned_and_complete() {
    assert!(FIXTURE.starts_with(&format!("# Official ACEmulator/ACE {PIN};")));
    let rows = fixture_rows();
    assert_eq!(
        rows.len(),
        WEENIE_ERROR_COUNT + WEENIE_ERROR_WITH_STRING_COUNT + CHAT_MESSAGE_TYPE_COUNT
    );
    for enum_name in ["WeenieError", "WeenieErrorWithString", "ChatMessageType"] {
        assert!(
            rows.iter().any(|row| row.enum_name == enum_name),
            "{enum_name} missing"
        );
    }
}

#[test]
fn weenie_error_matches_ace_fixture() {
    check(
        "WeenieError",
        WEENIE_ERROR_COUNT,
        &WeenieError::ALL,
        WeenieError::from_u32,
        WeenieError::value,
    );
}

#[test]
fn weenie_error_with_string_matches_ace_fixture() {
    check(
        "WeenieErrorWithString",
        WEENIE_ERROR_WITH_STRING_COUNT,
        &WeenieErrorWithString::ALL,
        WeenieErrorWithString::from_u32,
        WeenieErrorWithString::value,
    );
}

#[test]
fn chat_message_type_matches_ace_fixture() {
    check(
        "ChatMessageType",
        CHAT_MESSAGE_TYPE_COUNT,
        &ChatMessageType::ALL,
        ChatMessageType::from_u32,
        ChatMessageType::value,
    );
}

#[test]
fn chat_message_type_gap_is_undefined() {
    // ACE comments out 0x1A (ChatMessageType.cs:259); it must stay undefined.
    assert_eq!(ChatMessageType::from_u32(0x1A), None);
    assert_eq!(ChatMessageType::from_u32(0x1B), Some(ChatMessageType::X1B));
}
